&lt;p data-start=&quot;1761&quot; data-end=&quot;1793&quot;&gt;&lt;strong data-start=&quot;1761&quot; data-end=&quot;1793&quot;&gt;Hands-on Support (As Needed)&lt;/strong&gt;&lt;/p&gt;
